import fs from "node:fs";
import path from "node:path";
import { execSync } from "node:child_process";

const root = process.cwd();
const packagePath = path.join(root, "package.json");
const targetRelativePath = "src/styles/darkerTheme.css";
const targetPath = path.join(root, targetRelativePath);

if (!fs.existsSync(packagePath)) {
  console.error(
    "package.json was not found. Run this installer from the A-R-V1 repository root.",
  );
  process.exit(1);
}

let packageJson;

try {
  packageJson = JSON.parse(
    fs.readFileSync(packagePath, "utf8"),
  );
} catch (error) {
  console.error("Could not read package.json:", error);
  process.exit(1);
}

if (packageJson.name !== "roadsafe-ar") {
  console.error(
    `Expected the RoadSafe project (roadsafe-ar), but found "${packageJson.name ?? "unknown"}".`,
  );
  process.exit(1);
}

if (!fs.existsSync(targetPath)) {
  console.error(
    `${targetRelativePath} was not found. Install the workstation shell restructuring first.`,
  );
  process.exit(1);
}

const timestamp = new Date()
  .toISOString()
  .replace(/[:.]/g, "-");

const backupPath = path.join(
  root,
  ".roadsafe-ui-backup",
  timestamp,
  targetRelativePath,
);

fs.mkdirSync(path.dirname(backupPath), {
  recursive: true,
});

fs.copyFileSync(targetPath, backupPath);

